// The beat ring as a table (#558): every pixel the ring draws, in scan order, with what it ends up as: unlit (beat 1 a
// step brighter), all dark (the waiting look), and lit in its own section's live green. Generated by
// gen/ring_table_gen.c into src/ring_table.c: don't edit that file; regenerate it with `make tables`.
#ifndef DFW_RING_TABLE_H
#define DFW_RING_TABLE_H
#include <stdint.h>

typedef struct {
    /// y * 198 + x in the frame.
    uint16_t index;
    /// The unlit ring's gray and the all-dark ring's, each over the ground (a gray: one level for all three channels).
    uint8_t normal, dark;
    /// The beat whose section lights this pixel (1-4), 0 for none, and its color then.
    uint8_t beat, lit_r, lit_g, lit_b;
} dfw_ring_entry;

extern const dfw_ring_entry dfw_ring_table[];
extern const int dfw_ring_entries;

#endif
